    return float(v) if v is not None and math.isfinite(v) and v > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and r > 0:
            total += x * r ** 3
            weight += x
    return float(4.0 * math.pi * total / (3.0 * weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    nearest = [0.0] * n
    neighbors = s.get('neighbors', [])
    for b in neighbors:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[j] > 0 and (nearest[i] == 0 or d < nearest[i]):
            nearest[i] = d
    counts = [0.0] * n
    for b in neighbors:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and nearest[i] > 0 and d <= 1.25 * nearest[i]:
            counts[i] += occ[j]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * counts[i] for i in range(n)) / weight
    return float(math.sqrt(max(0.0, sum(occ[i] * (counts[i] - mean) ** 2 for i in range(n)) / weight)))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        valence = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and valence is not None:
            total += x * valence
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0
